namespace OneDevice.MasterClient.Core.Masters;

public enum PortEventKind
{
    /// <summary>IO-Link Event reported by the Device or generated by the master (see <see cref="PortEvent.LocalGenerated" />).</summary>
    Event,

    /// <summary>The Device left PREOPERATE / OPERATE (communication lost, e.g. reset or power off).</summary>
    CommunicationLost,

    /// <summary>The Device reached PREOPERATE / OPERATE again: a communication startup sequence took place.</summary>
    CommunicationStarted
}

/// <summary>Something that happened on a port, numbered in the order it was seen.</summary>
/// <param name="Sequence">Increasing number, unique per master session.</param>
/// <param name="Code">IO-Link EventCode (Events only), e.g. 0xFF91 DS_UPLOAD_REQ.</param>
/// <param name="Mode">Event mode as reported by the master (1 = single shot, 2 = disappears, 3 = appears).</param>
/// <param name="Type">Event type (1 = notification, 2 = warning, 3 = error).</param>
/// <param name="SensorStatus">Master sensor status bits at that moment (communication changes).</param>
public sealed record PortEvent(
    long Sequence,
    int Port,
    DateTimeOffset Timestamp,
    PortEventKind Kind,
    int Code = 0,
    int Mode = 0,
    int Type = 0,
    int Instance = 0,
    bool LocalGenerated = false,
    uint SensorStatus = 0);

/// <summary>Thread-safe buffer of the latest port events.</summary>
public sealed class PortEventLog(int capacity = 500)
{
    private readonly object _lock = new();
    private readonly Queue<PortEvent> _events = new();
    private long _sequence;

    public long LastSequence
    {
        get
        {
            lock (_lock) return _sequence;
        }
    }

    public PortEvent Add(int port, DateTimeOffset timestamp, PortEventKind kind, int code = 0, int mode = 0, int type = 0,
        int instance = 0, bool localGenerated = false, uint sensorStatus = 0)
    {
        lock (_lock)
        {
            var e = new PortEvent(++_sequence, port, timestamp, kind, code, mode, type, instance, localGenerated, sensorStatus);
            _events.Enqueue(e);
            while (_events.Count > capacity) _events.Dequeue();
            return e;
        }
    }

    /// <summary>Events of a port with a sequence number greater than <paramref name="after" />.</summary>
    public IReadOnlyList<PortEvent> After(long after, int? port = null)
    {
        lock (_lock) return _events.Where(e => e.Sequence > after && (port == null || e.Port == port)).ToList();
    }
}

/// <summary>
///     IO-Link EventQualifier fields. The TMG master reports MODE and TYPE as the raw qualifier bits (MODE in bits 7–6,
///     e.g. 0x40 / 0x80 / 0xC0; TYPE in bits 5–4, e.g. 0x10 / 0x20 / 0x30); they are normalized to 1–3 so that every
///     master reports the same values.
/// </summary>
public static class EventQualifier
{
    /// <summary>1 = single shot, 2 = disappears, 3 = appears.</summary>
    public static int Mode(byte mode) => mode > 3 ? (mode >> 6) & 0x03 : mode;

    /// <summary>1 = notification, 2 = warning, 3 = error.</summary>
    public static int Type(byte type) => type > 3 ? (type >> 4) & 0x03 : type;
}

/// <summary>IOLUSBIF20 sensor status bits (IOL_GetSensorStatus).</summary>
public static class SensorStatusBits
{
    public const uint Operate = 0x01;
    public const uint Preoperate = 0x02;
    public const uint EventAvailable = 0x04;
    public const uint PdValid = 0x08;
    public const uint WrongSensor = 0x10;
    public const uint StateKnown = 0x80;

    /// <summary>True / false when the master knows the sensor state, null otherwise.</summary>
    public static bool? IsCommunicating(uint status) =>
        (status & StateKnown) == 0 ? null : (status & (Operate | Preoperate)) != 0;
}
